spec rc=0
2:# Ledger helpers. LEDGER rows: date<TAB>sku<TAB>qty<TAB>kind<TAB>ref (kind IN or OUT).
3:LEDGER=${LEDGER:-data/ledger.tsv}
7:onhand() { awk -F'\t' -v s="$1" '!/^#/ && NF && $2 == s { if ($4 == "IN") t += $3; else t -= $3 } END { print t }' "$LEDGER"; }
 M .gitignore

